function p95(rs){return rs.length?pct(rs.map(r=>r.ms),95):NaN}
print('counts', 'stable='+stable.length, 'canary='+canary.length);
print('5xx stable='+stable.filter(r=>r.status>=500).length, '5xx canary='+canary.filter(r=>r.status>=500).length);
print('status codes', JSON.stringify(rows.reduce((a,r)=>{a[r.status]=(a[r.status]||0)+1;return a},{})));
for(const w of [[0,30],[30,60],[60,90],[90,120]]){
  const s=stable.filter(r=>r.t>=w[0]&&r.t<w[1]), c=canary.filter(r=>r.t>=w[0]&&r.t<w[1]);
  print('win '+w[0]+'-'+w[1]+'s canary_p95='+p95(c)+' stable_p95='+p95(s)+' canary_n='+c.length+' canary_5xx='+c.filter(r=>r.status>=500).length);
}
const lateC=canary.filter(r=>r.t>=60), lateS=stable.filter(r=>r.t>=60);
print('LAST60 canary p50/p95/p99='+pct(lateC.map(r=>r.ms),50)+'/'+p95(lateC)+'/'+pct(lateC.map(r=>r.ms),99));
print('LAST60 stable p50/p95/p99='+pct(lateS.map(r=>r.ms),50)+'/'+p95(lateS)+'/'+pct(lateS.map(r=>r.ms),99));
for(const p of ['/browse','/search','/checkout']){
  const c=lateC.filter(r=>r.path===p), s=lateS.filter(r=>r.path===p);
  print('LAST60 '+p+' canary_p95='+p95(c)+' stable_p95='+p95(s)+' canary_n='+c.length);
}
const first30=canary.filter(r=>r.t<30);
print('FIRST30 canary p95='+p95(first30)+' n='+first30.length);

function q(rs,p){return rs.length?pct(rs.map(r=>r.ms),p):NaN}
function man(rs,p){const a=rs.map(r=>r.ms).sort((x,y)=>x-y);return a[Math.min(a.length-1,Math.floor(p*a.length))]}
print('CONVENTION frac pct canary', q(canary,0.5), q(canary,0.95), q(canary,0.99));
print('CONVENTION int  pct canary', q(canary,50), q(canary,95), q(canary,99));
print('MANUAL canary p50/p95/p99', man(canary,0.5), man(canary,0.95), man(canary,0.99));
print('MANUAL stable p50/p95/p99', man(stable,0.5), man(stable,0.95), man(stable,0.99));
print('max canary', Math.max(...canary.map(r=>r.ms)), 'max stable', Math.max(...stable.map(r=>r.ms)));
const wins=[[0,30],[30,60],[60,90],[90,120]];
for(const w of wins){const c=canary.filter(r=>r.t>=w[0]&&r.t<w[1]), s=stable.filter(r=>r.t>=w[0]&&r.t<w[1]);
  print('WIN '+w[0]+'-'+w[1]+' canary_p95='+man(c,0.95)+' stable_p95='+man(s,0.95)+' canary_p50='+man(c,0.5)+' stable_p50='+man(s,0.5)+' n='+c.length+' 5xx='+c.filter(r=>r.status>=500).length);}
const L=rs=>rs.filter(r=>r.t>=60);
print('LAST60 all canary p50/p95/p99='+man(L(canary),0.5)+'/'+man(L(canary),0.95)+'/'+man(L(canary),0.99)+' stable='+man(L(stable),0.5)+'/'+man(L(stable),0.95)+'/'+man(L(stable),0.99));
for(const p of ['/browse','/search','/checkout']){const c=L(canary).filter(r=>r.path===p), s=L(stable).filter(r=>r.path===p);
  print('LAST60 '+p+' canary p50/p95='+man(c,0.5)+'/'+man(c,0.95)+' stable p50/p95='+man(s,0.5)+'/'+man(s,0.95)+' n='+c.length);}
print('FIRST30 all canary p95='+man(canary.filter(r=>r.t<30),0.95)+' stable p95='+man(stable.filter(r=>r.t<30),0.95));
print('5xx total canary='+canary.filter(r=>r.status>=500).length+' stable='+stable.filter(r=>r.status>=500).length+' non200='+rows.filter(r=>r.status!==200).length);

